import{_ as t,o as a,c as i,a6 as r,ag as o,ah as s,ai as l,aj as n,ak as d,al as c,am as h}from"./chunks/framework.Cpn2jE3L.js";const x=JSON.parse('{"title":"Metadata Settings","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/wordpress-document-repository/metadata-settings.md","filePath":"content/plugins/wordpress-document-repository/metadata-settings.md"}'),m={name:"content/plugins/wordpress-document-repository/metadata-settings.md"};function g(p,e,u,f,y,b){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="metadata-settings" tabindex="-1">Metadata Settings <a class="header-anchor" href="#metadata-settings" aria-label="Permalink to “Metadata Settings”">​</a></h1><p>Use Metadata settings to define the custom fields that appear on every document in the repository. These fields improve search, sorting, and filtering across both the standard and spreadsheet views.</p><p><img src="'+o+'" alt="Metadata Settings Overview:"></p><hr><h2 id="prerequisites-access" tabindex="-1">Prerequisites &amp; Access <a class="header-anchor" href="#prerequisites-access" aria-label="Permalink to “Prerequisites &amp; Access”">​</a></h2><ul><li>Document Repository plugin installed and enabled.</li><li>Admins or users with edit capability can create, edit, and delete metadata fields.</li></ul><hr><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to “Where to find it”">​</a></h2><p>In WordPress Admin: <strong>Document Repository → Metadata Settings</strong> (left nav).</p><p><img src="'+s+'" alt="Where To Find Metadata Settings"></p><hr><h2 id="what-you-can-configure" tabindex="-1">What you can configure <a class="header-anchor" href="#what-you-can-configure" aria-label="Permalink to “What you can configure”">​</a></h2><p>Each metadata field includes:</p><ul><li><strong>Field Label</strong> (required): The display name shown in the repository.</li><li><strong>Field Type</strong>: <code>Text</code>, <code>Date</code>, or <code>Taxonomy</code>.</li><li><strong>Description</strong>: Optional helper text.</li><li><strong>Taxonomy Terms</strong> (required when type is Taxonomy): A list of categories, one per line. For example, if a document repository is used by a Zoo, the taxonomy could be Animals: Ape, Bear, Coyote. The taxonomy is Animals, and the terms are Ape, Bear, Coyote.</li></ul><p><img src="'+l+'" alt="Metadata Field Form"></p><p>Notes:</p><ul><li>Field type is chosen at creation and cannot be changed later. You must create a new field.</li><li>Text and Date fields may have empty values; Taxonomy fields require terms.</li><li>New fields apply to newly uploaded documents, but values remain blank until edited in standard or spreadsheet mode.</li></ul><hr><h2 id="add-new-field" tabindex="-1">Add New Field <a class="header-anchor" href="#add-new-field" aria-label="Permalink to “Add New Field”">​</a></h2><ol><li>Go to <strong>Document Repository → Metadata Settings</strong>.</li><li>Click <strong>Add New Field</strong>.</li><li>Enter a <strong>Field Label</strong> (required).</li><li>Choose a <strong>Field Type</strong>: <ul><li><strong>Text</strong>: freeform text.</li><li><strong>Date</strong>: date value.</li><li><strong>Taxonomy</strong>: pick from predefined terms.</li></ul></li><li>(Taxonomy only) Enter <strong>Taxonomy Terms</strong> as a list, one line per term.</li><li>(Taxonomy only) Check <strong>Multiple Choice</strong> to allow selecting multiple taxonomy terms.</li><li>Optionally add a <strong>Description</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+n+'" alt="Add Metadata Field"></p><hr><h2 id="edit-a-field" tabindex="-1">Edit a field <a class="header-anchor" href="#edit-a-field" aria-label="Permalink to “Edit a field”">​</a></h2><ul><li>Click <strong>Edit</strong> beside a field.</li><li>Update the <strong>Label</strong>, <strong>Description</strong>, or (for Taxonomy) modify the <strong>Terms</strong>.</li><li><strong>Field Type is locked</strong> after creation.</li><li>Taxonomy terms can be modified but not fully removed; keep at least one term.</li><li>Save changes. Existing documents keep their prior values until each document is edited (standard or spreadsheet mode).</li></ul><p><img src="'+d+'" alt="Edit Metadata Field"></p><hr><h2 id="delete-a-field" tabindex="-1">Delete a field <a class="header-anchor" href="#delete-a-field" aria-label="Permalink to “Delete a field”">​</a></h2><ol><li>Click <strong>Delete</strong> beside a field.</li><li>In the confirmation dialog, review the warning: <ul><li>Deleting permanently removes the field and all its values from every document.</li><li>Dialog shows Field ID, Label, Type, and Description.</li></ul></li><li>Choose <strong>Delete Field</strong> to confirm, or <strong>Cancel</strong> to stop.</li></ol><p>Effect:</p><ul><li>The field (column) disappears from both standard and spreadsheet views.</li><li>All stored values for that field are removed.</li></ul><p><img src="'+c+'" alt="Delete Metadata Field"></p><hr><h2 id="using-metadata-in-the-repository" tabindex="-1">Using metadata in the repository <a class="header-anchor" href="#using-metadata-in-the-repository" aria-label="Permalink to “Using metadata in the repository”">​</a></h2><ul><li>New fields appear as columns in both views.</li><li>Enter or edit values per document in <strong>standard</strong> or <strong>spreadsheet</strong> mode.</li><li>Search by: <ul><li><strong>Text</strong>: match text strings.</li><li><strong>Date</strong>: filter by date.</li><li><strong>Taxonomy</strong>: filter by selected terms.</li></ul></li></ul><p><img src="'+h+'" alt="Using a Metadata Field"></p><hr><h2 id="tips-best-practices" tabindex="-1">Tips &amp; best practices <a class="header-anchor" href="#tips-best-practices" aria-label="Permalink to “Tips &amp; best practices”">​</a></h2><ul><li>Create only fields you will actively search or sort by; too many fields can impact performance and require horizontal scrolling.</li><li>Plan Taxonomy terms carefully to keep filters meaningful.</li><li>If you need a different Field Type, delete the old field and create a new one with the desired type.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li><strong>Fields not showing in repository views</strong>: Refresh the page and clear any caching plugins/CDN. Confirm the field exists in <strong>Metadata Settings</strong> and you have permission to view it.</li><li><strong>New field appears but values are blank</strong>: This is expected—new fields are blank until each document is edited in standard or spreadsheet mode.</li><li><strong>Cannot change Field Type</strong>: By design, the type is fixed after creation. Delete and recreate the field with the desired type.</li><li><strong>Taxonomy terms missing or not selectable</strong>: Ensure at least one term remains in the Taxonomy field. Edit the field and re-add terms if they were removed.</li><li><strong>Performance issues with many fields</strong>: Reduce the number of fields or limit very large term lists to avoid wide tables and heavy queries.</li></ul><hr><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to “Quick reference”">​</a></h2><ul><li><strong>Required</strong>: Field Label; Taxonomy Terms (for Taxonomy type).</li><li><strong>Field Type</strong>: Chosen once; cannot be changed later.</li><li><strong>Deletion</strong>: Permanent and removes all values.</li><li><strong>Who can manage</strong>: Admins or users with edit capability.</li><li><strong>Location</strong>: Document Repository → Metadata Settings.</li></ul>',44)])])}const w=t(m,[["render",g]]);export{x as __pageData,w as default};
